glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Outline {
  vec4 outlineColor;
  float outlineWidth;
};
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  vec4 finalColor = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    finalColor.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    finalColor.a *= texture_tmp.a;
  #else
    finalColor *= texture_tmp;
  #endif
    finalColor = mix(outlineColor, o.rgba, o.a);
    float alpha_Left = texture2D(texture, v_uv0 + vec2(outlineWidth, 0)).a;
    float alpha_Right = texture2D(texture, v_uv0 + vec2(-outlineWidth, 0)).a;
    float alpha_Top = texture2D(texture, v_uv0 + vec2(0, outlineWidth)).a;
    float alpha_Bottom = texture2D(texture, v_uv0 + vec2(0, -outlineWidth)).a;
    float alpha_LeftTop = texture2D(texture, v_uv0 + vec2(outlineWidth, outlineWidth)).a;
    float alpha_RightTop = texture2D(texture, v_uv0 + vec2(-outlineWidth, outlineWidth)).a;
    float alpha_RightBottom = texture2D(texture, v_uv0 + vec2(-outlineWidth, -outlineWidth)).a;
    float alpha_LeftBottom = texture2D(texture, v_uv0 + vec2(outlineWidth, -outlineWidth)).a;
    float outlineAlpha = alpha_Left + alpha_Right + alpha_Top + alpha_Bottom
    + alpha_LeftTop + alpha_RightTop + alpha_RightBottom + alpha_LeftBottom;
    finalColor.a = outlineAlpha;
  #endif
  o *= v_color;
  gl_FragColor = finalColor;
}

